@MainActor func transient_PackageSlavePad_selectionDisplay (
       _ prefs_selectionHiliteColor : NSColor,              
       _ self_xCenter : CanariLength,                       
       _ self_yCenter : CanariLength,                       
       _ self_width : CanariLength,                         
       _ self_height : CanariLength,                        
       _ self_padShape : PadShape
) -> EBShape {
//--- START OF USER ZONE 2
    let xCenter = self_xCenter
    let yCenter = self_yCenter
    let width = self_width
    let height = self_height
    let rPad = CanariRect (left: xCenter - width / 2.0, bottom: yCenter - height / 2.0, width: width, height: height)
    var bp : BezierPath
    switch self_padShape {
    case .rect :
      bp = BezierPath (rect: rPad)
    case .round :
      if width < height {
        bp = BezierPath (roundedRect: rPad, xRadius: width / 2.0, yRadius: width / 2.0)
      }else if width > height {
        bp = BezierPath (roundedRect: rPad, xRadius: height / 2.0, yRadius: height / 2.0)
      }else{
        bp = BezierPath (ovalIn: rPad)
      }
    case .octo :
      bp = BezierPath (octogonInRect: rPad)
    }
    bp.lineWidth = CanariLength.pt (0.25)
    bp.lineCapStyle = .round
    return EBShape (stroke: [bp], prefs_selectionHiliteColor)
//--- END OF USER ZONE 2
}

